def simulate(inp, verbose=False):
    R,C = len(inp), len(inp[0])
    out = [row[:] for row in inp]
    # find seed
    seed = next((r,c) for r in range(R) for c in range(C) if inp[r][c]==2)
    out[seed[0]][seed[1]] = 2
    # direction: from nearest edge among the four sides; if on top row -> down, etc.
    r0,c0 = seed
    cands = []
    if r0==0: cands.append((1,0))
    if r0==R-1: cands.append((-1,0))
    if c0==0: cands.append((0,1))
    if c0==C-1: cands.append((0,-1))
    if not cands:  # fallback: move toward farther side? use dominant open direction
        cands=[(1,0)]
    dr,dc = cands[0]
    seen=set()
    stack=[(r0,c0,dr,dc)]
    while stack:
        r,c,dr,dc = stack.pop()
        if (r,c,dr,dc) in seen: continue
        seen.add((r,c,dr,dc))
        nr,nc = r+dr, c+dc
        if not (0<=nr<R and 0<=nc<C):
            continue  # flowed off edge
        if inp[nr][nc]==8:
            # spread perpendicular from (r,c)
            for pdr,pdc in ((dc,dr),(-dc,-dr)):
                pr,pc = r,c
                while True:
                    pr+=pdr; pc+=pdc
                    if not (0<=pr<R and 0<=pc<C):
                        break  # edge, no spawn
                    if inp[pr][pc]==8:
                        break  # wall perpendicular? just stop (didn't occur in demos)
                    out[pr][pc]=2
                    # wall cell ahead in original direction?
                    wr,wc = pr+dr, pc+dc
                    if 0<=wr<R and 0<=wc<C and inp[wr][wc]==8:
                        continue  # keep spreading, wall continues
                    else:
                        # gap (or open) ahead -> color gap, spawn
                        if 0<=wr<R and 0<=wc<C:
                            out[wr][wc]=2
                            stack.append((wr,wc,dr,dc))
                        break
        else:
            out[nr][nc]=2
            stack.append((nr,nc,dr,dc))
    return out

def diff(a,b):
    return [(r,c,a[r][c],b[r][c]) for r in range(len(a)) for c in range(len(a[0])) if a[r][c]!=b[r][c]]

